interface.definition:
a!localVariables(
  local!isNewVersion: if(
    a!isNullOrEmpty(ri!nomination.createdOn),
    true,
    if(
      todatetime(ri!nomination.createdOn) > #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12333392",
      true,
      false
    )
  ),
  local!isOldVersion: if(
    a!isNullOrEmpty(ri!nomination.createdOn),
    false,
    if(
      todatetime(ri!nomination.createdOn) < #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11589045",
      true,
      false
    )
  ),
  local!isRequestBeforeV4:if(
    a!isNullOrEmpty(ri!nomination.createdOn),
    false,
    if(
      todatetime(ri!nomination.createdOn)<#"_a-0000eab6-1962-8000-9c4d-011c48011c48_12333392",
      true,
      false)
  ),
  #"SYSTEM_SYSRULES_sectionLayout_v1"(
    label: "HR Review",
    labelColor: "SECONDARY",
    showWhen: ri!showWhen,
    contents: {
      #"SYSTEM_SYSRULES_richTextDisplayField"(
        labelPosition: "COLLAPSED",
        value: {
          #"SYSTEM_SYSRULES_richTextItem_v1"(
            text: { "To be completed by HR Personnel" },
            size: "SMALL",
            style: "EMPHASIS"
          )
        }
      ),
      #"SYSTEM_SYSRULES_cardLayout"(
        contents: {
          #"SYSTEM_SYSRULES_columnsLayout"(
            columns: {
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_textField"(
                    /*Changes according to APAP-19643- Updation of verbiage*/
                    /*label: "Does the individual have an AQR 1 or 2?",*/
                    label: "Does the individual have an AQR 1, 2 or 3?",
                    labelPosition: "ABOVE",
                    value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                      value: index(ri!nomination, "isAQR1or2", tostring({})),
                      isBoolean: false
                    ),
                    readOnly: true
                  ),
                  #"SYSTEM_SYSRULES_textField"(
                    label: "Is the candidate in good standing within the past 3 fiscal years?",
                    labelPosition: "ABOVE",
                    helpTooltip: if(
                      toboolean(local!isNewVersion) = true,
                      "Good Standing Includes US-FM HR People Support check of PIP Database, IEM (Investigations), YELP (year-end low performer) flag, and Functional LP database",
                      "Coming Soon ..."),
                    value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                      value: index(
                        ri!nomination,
                        "isCandidateGoodStanding",
                        toboolean({})
                      ),
                      isBoolean: true
                    ),
                    readOnly: true
                  ),
                  #"SYSTEM_SYSRULES_textField"(
                    label: "Is additional vetting required?",
                    labelPosition: "ABOVE",
                    value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                      value: index(
                        ri!nomination,
                        "isVettingRequired",
                        toboolean({})
                      ),
                      isBoolean: true
                    ),
                    readOnly: true
                  ),
                  #"SYSTEM_SYSRULES_paragraphField"(
                    label: "HR/Other Comments",
                    labelPosition: "ABOVE",
                    value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                      value: index(ri!nomination, "hrComments", null),
                      isBoolean: false
                    ),
                    height: "MEDIUM",
                    readOnly: true
                  )
                }
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_sideBySideLayout"(
                    items: {
                      #"SYSTEM_SYSRULES_sideBySideItem"(
                        item: #"SYSTEM_SYSRULES_textField"(
                          label: "Provide Years of Service",
                          labelPosition: "ABOVE",
                          value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                            value: index(ri!nomination, "yearsofServiceHR", null),
                            isBoolean: false
                          ),
                          readOnly: true
                        )
                      ),
                      #"SYSTEM_SYSRULES_sideBySideItem"(
                        item: #"SYSTEM_SYSRULES_textField"(
                          label: "Years of Service per nomination",
                          labelPosition: "ABOVE",
                          readOnly: true,
                          value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                            value: index(ri!nomination, "yearsWithFirm", {}),
                            isBoolean: false
                          )
                        )
                      )
                    }
                  ),
                  #"SYSTEM_SYSRULES_sideBySideLayout"(
                    items: {
                      #"SYSTEM_SYSRULES_sideBySideItem"(
                        item: #"SYSTEM_SYSRULES_textField"(
                          label: "Expected MD Promotion Date per latest available pipeline",
                          labelPosition: "ABOVE",
                          value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                            value: index(ri!nomination, "mdPromotionDateHR", null),
                            isBoolean: false
                          ),
                          readOnly: true
                        )
                      ),
                      #"SYSTEM_SYSRULES_sideBySideItem"(
                        item: #"SYSTEM_SYSRULES_textField"(
                          label: "Expected MD Promotion Date per nomination",
                          labelPosition: "ABOVE",
                          readOnly: true,
                          value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                            value: index(ri!nomination, "mdPromotionDate", {}),
                            isBoolean: false
                          )
                        )
                      )
                    }
                  ),
                  #"SYSTEM_SYSRULES_sideBySideLayout"(
                    items: {
                      #"SYSTEM_SYSRULES_sideBySideItem"(
                        item: #"SYSTEM_SYSRULES_textField"(
                          label: "Expected Partner Promotion Date per latest available pipeline",
                          labelPosition: "ABOVE",
                          value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                            value: index(
                              ri!nomination,
                              "partnerPromotionDateHR",
                              null
                            ),
                            isBoolean: false
                          ),
                          readOnly: true
                        )
                      ),
                      #"SYSTEM_SYSRULES_sideBySideItem"(
                        item: #"SYSTEM_SYSRULES_textField"(
                          label: if(toboolean(local!isRequestBeforeV4),
                          "Is this candidate a future partner promote?",
                          "Is this candidate in your partner pipeline?"),
                          labelPosition: "ABOVE",
                          value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                            value: index(
                              ri!nomination,
                              "isFuturePartnerPromote",
                              toboolean({})
                            ),
                            isBoolean: true
                          ),
                          readOnly: true
                        ),
                        showWhen: if(
                          toboolean(local!isOldVersion) = true,
                          false,
                          true
                        )
                      )



                    },
                    /*Removing the visibility condition as per story APAP-28579 - Sahana Ananth on 7-Nov-2025 */

                  ),
                  /* Adding the following 2 fields per story -- Sahana Ananth on 7-Nov-2025 */
                  #"SYSTEM_SYSRULES_sideBySideLayout"(
                    items: {
                      #"SYSTEM_SYSRULES_sideBySideItem"(
                        item: #"SYSTEM_SYSRULES_textField"(
                          label: "Which pathway is most applicable to the candidate per HR",
                          labelPosition: "ABOVE",
                          value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                            value: index(
                              ri!nomination,
                              "applicablePathwayHR",
                              null
                            ),
                            isBoolean: false
                          ),
                          readOnly: true
                        )
                      ),
                      #"SYSTEM_SYSRULES_sideBySideItem"(
                        item: #"SYSTEM_SYSRULES_textField"(
                          label: "Which pathway is most applicable to the candidate per nomination",
                          labelPosition: "ABOVE",
                          readOnly: true,
                          value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                            value: index(
                              ri!nomination,
                              "applicablePathway",
                              {}
                            ),
                            isBoolean: false
                          )
                        )
                      )
                    }
                  ),
                  #"SYSTEM_SYSRULES_sideBySideLayout"(
                    items: {
                      #"SYSTEM_SYSRULES_sideBySideItem"(),
                      if(
                        toboolean(local!isOldVersion) = true,
                        #"SYSTEM_SYSRULES_sideBySideItem"(
                          item: #"SYSTEM_SYSRULES_textField"(
                            label: "Expected Partner Promotion Date per nomination",
                            labelPosition: "ABOVE",
                            readOnly: true,
                            value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                              value: index(
                                ri!nomination,
                                "partnerPromotionDate",
                                {}
                              ),
                              isBoolean: false
                            )
                          )
                        ),
                        #"SYSTEM_SYSRULES_sideBySideItem"()
                      )
                    }
                  )
                },
                width: if(
                  #"SYSTEM_SYSRULES_isPageWidth"({ "DESKTOP_WIDE" }),
                  "WIDE_PLUS",
                  if(
                    #"SYSTEM_SYSRULES_isPageWidth"({ "DESKTOP" }),
                    "WIDE",
                    "AUTO"
                  )
                )
              )
            },
            showDividers: true
          ),

        }
      )
    },
    isCollapsible: true,
    divider: "ABOVE",
    dividerWeight: "THIN",
    marginBelow: "STANDARD"
  )
)
